document.addEventListener("brio:init",()=>{Brio.addTransitionEngine({name:"Web Animations API",validate:e=>e instanceof Animation,play:(e,n)=>{e.playbackRate<0&&(e.reverse(),e.pause()),e.currentTime!=(e=>{let n=e.effect;return n?Number(n.getTiming().duration):0})(e)?e.play():n()},reverse:(e,n)=>{0==e.currentTime?n():e.playbackRate>0&&(e.reverse(),e.pause()),0!=e.currentTime?e.play():n()},onComplete:(e,n)=>{e.onfinish=n}})});